package util //nolint:revive // util namespace is intentional for shared helpers

import (
	"crypto/rand"
	"math/big"
	"net/mail"
	"strconv"
	"strings"

	"github.com/google/uuid"
)

// ConvertStringToInt32 converts a string to int32.
func ConvertStringToInt32(src string) (int32, error) {
	parsed, err := strconv.ParseInt(src, 10, 32)
	if err != nil {
		return 0, err
	}
	return int32(parsed), nil
}

// HasPrefixes returns true if the string s has any of the given prefixes.
func HasPrefixes(src string, prefixes ...string) bool {
	for _, prefix := range prefixes {
		if strings.HasPrefix(src, prefix) {
			return true
		}
	}
	return false
}

// ValidateEmail validates the email.
func ValidateEmail(email string) bool {
	if _, err := mail.ParseAddress(email); err != nil {
		return false
	}
	return true
}

func GenUUID() string {
	return uuid.New().String()
}

var letters = []rune("0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")

// RandomString returns a random string with length n.
func RandomString(n int) (string, error) {
	var sb strings.Builder
	sb.Grow(n)
	for i := 0; i < n; i++ {
		// The reason for using crypto/rand instead of math/rand is that
		// the former relies on hardware to generate random numbers and
		// thus has a stronger source of random numbers.
		randNum, err := rand.Int(rand.Reader, big.NewInt(int64(len(letters))))
		if err != nil {
			return "", err
		}
		if _, err := sb.WriteRune(letters[randNum.Uint64()]); err != nil {
			return "", err
		}
	}
	return sb.String(), nil
}

// ReplaceString replaces all occurrences of old in slice with new.
func ReplaceString(slice []string, old, new string) []string {
	for i, s := range slice {
		if s == old {
			slice[i] = new
		}
	}
	return slice
}

package filter

import (
	"context"
	"fmt"
)

// AppendConditions compiles the provided filters and appends the resulting SQL fragments and args.
func AppendConditions(ctx context.Context, engine *Engine, filters []string, dialect DialectName, where *[]string, args *[]any) error {
	for _, filterStr := range filters {
		stmt, err := engine.CompileToStatement(ctx, filterStr, RenderOptions{
			Dialect:           dialect,
			PlaceholderOffset: len(*args),
		})
		if err != nil {
			return err
		}
		if stmt.SQL == "" {
			continue
		}
		*where = append(*where, fmt.Sprintf("(%s)", stmt.SQL))
		*args = append(*args, stmt.Args...)
	}
	return nil
}

package base

import "regexp"

var (
	UIDMatcher = regexp.MustCompile("^[a-zA-Z0-9]([a-zA-Z0-9-]{0,34}[a-zA-Z0-9])?$")
)

args.command:
perl -e '
use strict;
use warnings;

# Collect all go files
open my $find, "find /bench/repo -name \"*.go\" ! -path \"*/web/*\" ! -path \"*/.git/*\" ! -path \"*/proto/gen/*\" |" or die;
my @gofiles;
while (<$find>) { chomp; push @gofiles, $_; }
close $find;

# Read all files into memory
my %content; # path => text
my %pkg;     # path => package
for my $p (@gofiles) {
  open my $fh, "<", $p or die $p;
  local $/;
  my $t = <$fh>;
  close $fh;
  $content{$p} = $t;
  if ($t =~ /^package\s+(\w+)/m) { $pkg{$p} = $1; }
}

# Extract internal decls
my @decls;
for my $p (grep { m{/internal/} && $_ !~ /_test\.go$/ } @gofiles) {
  my $line = 0;
  for my $l (split /\n/, $content{$p}) {
    $line++;
    if ($l =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z0-9_]+)\s*\(/) {
      my ($recv, $name) = ($1 // "", $2);
      next if $name eq "init";
      my $recv_type = "";
      if ($recv ne "") {
        my @pp = split /\s+/, $recv;
        $recv_type = $pp[-1];
        $recv_type =~ s/^\*//;
      }
      push @decls, {
        name => $name,
        recv => $recv_type,
        path => $p,
        line => $line,
        pkg => $pkg{$p},
        exported => ($name =~ /^[A-Z]/) ? 1 : 0,
        is_method => $recv_type ? 1 : 0,
      };
    }
  }
}

# Count callers
my @results;
for my $d (@decls) {
  my $name = $d->{name};
  my $pkgname = $d->{pkg};
  my $sites = 0;
  my $files = 0;
  my $prod_sites = 0;
  my $prod_files = 0;
  my @sample;
  for my $p (@gofiles) {
    my $t = $content{$p};
    my $count = 0;
    if ($d->{is_method}) {
      # .Name(  — method call
      while ($t =~ /\.$name\s*\(/g) { $count++; }
    } else {
      # same package: Name( but not func Name(
      # other package: pkg.Name(
      if (($pkg{$p}//"") eq $pkgname) {
        while ($t =~ /(?<!func )(?<![.\w])$name\s*\(/g) { $count++; }
        # subtract declaration
        $count-- if $p eq $d->{path};
      } else {
        while ($t =~ /\b\Q$pkgname\E\.$name\s*\(/g) { $count++; }
      }
    }
    next unless $count > 0;
    $sites += $count;
    $files++;
    if ($p !~ /_test\.go$/) {
      $prod_sites += $count;
      $prod_files++;
    }
    push @sample, "$p:$count" if @sample < 3;
  }
  push @results, { %$d, sites=>$sites, files=>$files, prod_sites=>$prod_sites, prod_files=>$prod_files, sample=>join(",", @sample) };
}

# Sort by prod_sites then all sites
@results = sort { $b->{prod_sites} <=> $a->{prod_sites} || $b->{sites} <=> $a->{sites} } @results;

print "TOP by production call sites:\n";
printf "%-40s %-8s %5s %5s %5s %5s  %s\n", "symbol", "method", "psite", "pfile", "asite", "afile", "path";
for my $i (0..39) {
  my $r = $results[$i];
  last unless $r;
  printf "%-40s %-8s %5d %5d %5d %5d  %s:%d\n",
    ($r->{recv} ? "$r->{recv}.$r->{name}" : $r->{name}),
    $r->{is_method} ? "yes" : "no",
    $r->{prod_sites}, $r->{prod_files}, $r->{sites}, $r->{files},
    $r->{path}, $r->{line};
}
'

